import{_ as t,o,c as a,a5 as s}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Five-State Inline Task Editing, Role-Scoped Subtasks & Sectioned Specialized Editors","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/04-task-chat-vault/task-subtask-and-inline-workflow/spec.md","filePath":"feature/modules/04-task-chat-vault/task-subtask-and-inline-workflow/spec.md"}'),r={name:"feature/modules/04-task-chat-vault/task-subtask-and-inline-workflow/spec.md"};function i(n,e,d,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="five-state-inline-task-editing-role-scoped-subtasks-sectioned-specialized-editors" tabindex="-1">Five-State Inline Task Editing, Role-Scoped Subtasks &amp; Sectioned Specialized Editors <a class="header-anchor" href="#five-state-inline-task-editing-role-scoped-subtasks-sectioned-specialized-editors" aria-label="Permalink to &quot;Five-State Inline Task Editing, Role-Scoped Subtasks &amp; Sectioned Specialized Editors&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>task-subtask-and-inline-workflow</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>04-task-chat-vault</code> — Task Workflow, Realtime Workspace Chat &amp; Encrypted S3 Vault</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>subtask-role-workspaces</code>, <code>task-creator-assignment</code>, <code>task-five-state-inline-edit</code>, <code>task-structure-simplification</code>, <code>task-unsaved-confirmation</code>, <code>task-write-start</code>, <code>workspace-task-real-data</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow</a> (<code>3.6.1–3.6.10</code>, <code>3.6.34–3.6.35</code>)</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Consolidate BrandHub&#39;s end-to-end Task authoring and execution UX: simplified 5-state Task workflow (<code>TODO</code>, <code>IN_PROGRESS</code>, <code>INTERNAL_REVIEW</code>, <code>CLIENT_REVIEW</code>, <code>APPROVED</code> / <code>PUBLISHED</code>), inline field editing (<code>TaskWorkflowController</code>), <code>Creator</code> assignment &amp; auto-start on &#39;Write Post&#39; (<code>task-write-start</code>), role-scoped <strong>Subtasks</strong> (<code>CampaignSubtaskController</code>) &amp; <strong>Multi-Section Specialized Task Editors</strong> (<code>TaskSectionController</code> for Event, KOL, Newsletter, Press, Survey, Workshop), unsaved-change navigation guards, and 100% real Campaign/Task data binding.</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As a <code>Manager</code> or <code>Owner</code>, I want inline editing of Task assignee, priority, deadline, and structured sections (<code>TaskSectionController</code>) with independent per-section review/return cycles so complex deliverables (KOL briefs, Events, Newsletters, Press releases) don&#39;t require rejecting an entire Task over one paragraph.</li><li>As a <code>Creator</code>, I want clicking &#39;Write Post&#39; on an assigned <code>TODO</code> Task to automatically start the Task (<code>IN_PROGRESS</code>) and protect my unsaved rich-text edits against accidental navigation loss.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><p><strong>Five-State Workflow &amp; Inline Field Editing (<code>task-five-state-inline-edit</code>, <code>task-structure-simplification</code>, <code>task-creator-assignment</code>):</strong> <code>TaskWorkflowController</code> (<code>GET /workflow</code>, <code>PATCH /detail</code>, <code>PATCH /field</code>, <code>POST /assign</code>, <code>POST /start</code>, <code>GET /member-options</code>) enables authorized <code>Owner</code>/<code>Manager</code> inline updates to assignee (<code>Creator</code>/<code>Manager</code>), priority, and dates with immediate validation and optimistic UI updates.</p></li><li><p><strong>Auto-Start on Write &amp; Unsaved-Change Protection (<code>task-write-start</code>, <code>task-unsaved-confirmation</code>):</strong> Opening the Content Editor and initiating &#39;Write Post&#39; as the assigned <code>Creator</code> transitions <code>TODO -&gt; IN_PROGRESS</code> via <code>POST /tasks/{taskId}/start</code>. Dirty editor state triggers both React Router blocker confirmation and browser <code>beforeunload</code> warning.</p></li><li><p><strong>Role-Scoped Subtasks &amp; Specialized Section Editors (<code>subtask-role-workspaces</code>):</strong> <code>CampaignSubtaskController</code> (<code>/tasks/{taskId}/subtasks</code>) manages ordered checklist subtasks, while <code>TaskSectionController</code> (<code>/tasks/{taskId}/sections/{sectionKey}</code> + <code>/submit</code>, <code>/approve</code>, <code>/return</code>, <code>/reopen</code>, <code>/versions</code>, <code>/restore/{versionNo}</code>) powers specialized editors (<code>event-editor</code>, <code>kol-editor</code>, <code>newsletter-editor</code>, <code>press-editor</code>, <code>survey-editor</code>, <code>workshop-editor</code>) backed by MongoDB <code>task_sections</code>, <code>task_section_versions</code>, and <code>task_section_events</code>.</p></li><li><p><strong>100% Real Workspace &amp; Campaign Task Views (<code>workspace-task-real-data</code>):</strong> Table (<code>TaskTable.tsx</code>), Kanban (<code>TaskBoardView.tsx</code>), Calendar (<code>TaskCalendarTimeline.tsx</code>), and Gantt (<code>TaskGanttView.tsx</code>) query live <code>GET /api/v1/workspaces/{workspaceId}/tasks</code> with zero hardcoded demo arrays.</p></li><li><p><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>tasks.{workflow,inline,subtasks,sections,unsavedConfirm}.*</code> in <code>src/i18n/locales/{vi,en}/tasks.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</p></li><li><p><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</p></li><li><p><strong>Editable KOL spreadsheet (Web):</strong> Users can open an editable field directly in the spreadsheet, including empty values and structured shortlist rows. Both views reflect edits immediately through the same section draft. Section permissions apply to both views, and existing save and review actions handle the shared draft. The new spreadsheet hint and controls are available in Vietnamese and English and use semantic theme tokens in light and dark modes.</p></li><li><p><strong>Task file exports (Web):</strong> The workspaces for Post, Short Video, Survey, Event, Press, KOL, Workshop, and Newsletter offer separate PDF, Word, and Excel downloads with format icons. The same options are available from task overview surfaces that show exportable work. Exports follow the existing section visibility, draft labeling, and authorization rules. Controls use parallel Vietnamese and English labels and semantic light/dark styling.</p></li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/tasks/{index,detail}.tsx</code>, <code>pages/tasks/components/views/*</code>, <code>pages/tasks/{event,kol,newsletter,press,survey,workshop}-editor/index.tsx</code>, <code>components/task-sections/SectionReturnDialog.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/content/{TaskListScreen,TaskKanbanScreen,TaskDetailScreen}.tsx</code>, <code>src/screens/content-writing/ContentWritingEditorScreen.tsx</code>, <code>src/services/{taskService,taskSectionService}.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/tasks &amp; GET /{taskId}</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>TaskController</code> -&gt; live task list &amp; detail across Table, Kanban, Calendar, Gantt</td></tr><tr><td style="text-align:left;"><code>PATCH /api/v1/workspaces/{workspaceId}/tasks/{taskId}/field &amp; POST /assign &amp; POST /start</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>TaskWorkflowController</code> -&gt; inline field mutation, Creator assignment &amp; write-start transition</td></tr><tr><td style="text-align:left;"><code>GET/POST/PATCH/PUT /api/v1/workspaces/{workspaceId}/tasks/{taskId}/subtasks/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>CampaignSubtaskController</code> -&gt; role-aware subtask CRUD, status toggle &amp; reorder</td></tr><tr><td style="text-align:left;"><code>GET/PATCH/POST /api/v1/workspaces/{workspaceId}/tasks/{taskId}/sections/{sectionKey}/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>TaskSectionController</code> &amp; <code>WorkspaceSectionController</code> -&gt; sectioned authoring, granular return/approve &amp; version restore</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Client Visibility Boundary:</strong> <code>Client</code> sees tasks and sections at <code>CLIENT_REVIEW</code> / <code>APPROVED</code> stages (<code>GET /sections/client-pending</code>) and never sees raw unsubmitted internal drafts (<code>TODO</code> / <code>IN_PROGRESS</code>).</li><li><strong>Concurrent Yjs / Snapshot Edit:</strong> <code>task_content_operations</code> and <code>task_content_snapshots</code> preserve version history (<code>FR 3.6.35</code>) alongside section version snapshots.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow</a> (<code>3.6.1–3.6.10</code>, <code>3.6.34–3.6.35</code>)</li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/05-content-task-workflow.html">BA 05 Content &amp; Task Workflow</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const k=t(r,[["render",i]]);export{u as __pageData,k as default};
